 private Teacher displayedTeacher(){if(overview==null||overview.getTeacher()==null)return null;Teacher copy=gson.fromJson(gson.toJson(overview.getTeacher()),Teacher.class);TeacherChangeRequest pending=overview.getPendingRequest();if(pending!=null&&pending.getStatus()==StudentChangeStatus.PENDING&&pending.getItems()!=null)for(TeacherChangeItem item:pending.getItems())if(EDITABLE.contains(item.getFieldName()))write(copy,item.getFieldName(),item.getNewValue()==null?"":item.getNewValue());return copy;}
