 private void applyReviewBucket(){
  unfinishedReviewButton.setSelected(!showCompletedReviews);completedReviewButton.setSelected(showCompletedReviews);
  requestReviewCol.setVisible(showCompletedReviews);
  reviewFiltered=reviewRequests.stream().filter(r->show(r.getTeacherId()).toLowerCase(java.util.Locale.ROOT).contains(teacherReviewSearchIdField.getText().trim().toLowerCase(java.util.Locale.ROOT))).filter(r->reviewStatusText(r.getStatus()).contains(teacherReviewSearchStatusField.getText().trim())||r.getStatus().name().equalsIgnoreCase(teacherReviewSearchStatusField.getText().trim())).filter(r->showCompletedReviews?r.getStatus()!=StudentChangeStatus.PENDING:r.getStatus()==StudentChangeStatus.PENDING).toList();reviewPage=1;renderReviewPage();
 }
