   addCardField(grid,"出生年月",record.getBirthDate(),1,0);addCardField(grid,"健康状况",record.getHealthStatus(),1,1);
   addCardField(grid,"户口所在地",record.getRegisteredResidence(),2,0);addCardField(grid,"联系电话",record.getPhone(),2,1);
   addCardField(grid,"工作单位",record.getWorkplace(),3,0);addCardField(grid,"工作单位地址",record.getWorkplaceAddress(),3,1);
